import requests
import json
import pandas as pd
import seaborn as sns
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not url or not isinstance(url, str):
        raise Exception("Invalid URL provided.")
    try:
        response = requests.get(url, headers=HEADERS, params=parameters, timeout=10)
        response.raise_for_status()
        data = response.json()
        if not data:
            raise Exception("Empty data returned from API.")
        if isinstance(data, list):
            df = pd.DataFrame(data)
        elif isinstance(data, dict):
            if 'data' in data:
                df = pd.DataFrame(data['data'])
            elif 'results' in data:
                df = pd.DataFrame(data['results'])
            else:
                df = pd.DataFrame([data])
        else:
            raise Exception("Invalid data format from API.")
        if df.empty:
            raise Exception("DataFrame is empty after conversion.")
        numeric_cols = df.select_dtypes(include=['number']).columns
        if len(numeric_cols) < 2:
            raise Exception("Not enough numeric columns for correlation heatmap.")
        corr = df[numeric_cols].corr()
        ax = sns.heatmap(corr, annot=True, cmap='coolwarm', square=True)
        ax.set_title('Correlation Heatmap')
        return df, ax
    except requests.RequestException as e:
        raise Exception(f"URL cannot be accessed: {e}")
    except (ValueError, TypeError, KeyError) as e:
        raise Exception(f"Invalid data: {e}")
